/* Cyber-Bridge Range — scenarii 1-5 / scenarios 1-5 */
(function(){
const t=(ro,en)=>({ro:ro,en:en});
const S=window.SCENARIOS={};

S.health={
 title:t("Ransomware în noaptea de sâmbătă spre duminică","Ransomware on the Saturday night"),
 brief:t("Criptarea a început la 02:10. Este 06:40. Asistenta de la recepție nu poate deschide programările. Blocul operator are 4 intervenții la ora 08:00.","Encryption started at 02:10. It is now 06:40. The receptionist cannot open the appointment system. The operating theatre has 4 procedures at 08:00."),
 steps:[
 {tp:"T+0",ck:"06:40",src:t("Recepție, locația centrală","Reception, main site"),
  msg:t("„Nu se deschide nimic. Nici programările, nici dosarele. Pe ecran scrie ceva în engleză și e un fișier pe desktop care nu era ieri.”","\"Nothing opens. Not the appointments, not the records. There's something in English on the screen and a file on the desktop that wasn't there yesterday.\""),
  q:t("Care este primul lucru pe care îl faci?","What is the first thing you do?"),
  o:[{t:t("Deconectezi de la rețea stația de la recepție și suni persoana de gardă IT. Nu oprești nimic altceva până nu știi amploarea.","Disconnect the reception workstation from the network and call the on-call IT contact. Stop nothing else until you know the extent."),
      d:{clin:1,data:1,legal:0,evi:2},
      c:t("Corect ca reflex inițial. Izolarea unei stații oprește propagarea de pe ea fără să distrugă probe și fără să scoată din funcțiune sisteme de care s-ar putea să mai ai nevoie. Ceasul însă curge: ai 80 de minute până la primul pacient.","Correct as a first reflex. Isolating one workstation stops propagation from it without destroying evidence or taking down systems you may still need. But the clock is running: 80 minutes until the first patient."),alt:null},
     {t:t("Oprești imediat toate serverele, ca să nu se cripteze mai mult.","Shut down all servers immediately so nothing more gets encrypted."),
      d:{clin:-2,data:0,legal:0,evi:-3},
      c:t("Ai oprit propagarea, dar ai pierdut memoria volatilă a sistemelor — adesea singurul loc unde se vede ce a rulat și de unde a venit. Ai pierdut și accesul la rezultatele de laborator de care blocul operator are nevoie la 08:00.","You stopped propagation but lost the systems' volatile memory — often the only place showing what ran and where it came from. You also lost access to the lab results the theatre needs at 08:00."),
      alt:t("Izolarea de rețea oprește propagarea fără să distrugă probele. Oprirea brutală se rezervă cazurilor în care criptarea e vizibil în desfășurare pe sisteme critice.","Network isolation stops propagation without destroying evidence. A hard shutdown is reserved for cases where encryption is visibly in progress on critical systems.")},
     {t:t("Ceri recepției să repornească și să încerce din nou, poate e o eroare de rețea.","Ask reception to reboot and try again — it might be a network error."),
      d:{clin:-1,data:-1,legal:0,evi:-2},
      c:t("Repornirea nu rezolvă nimic și poate declanșa etape ale malware-ului programate la boot. S-au pierdut 12 minute și starea sistemului.","Rebooting solves nothing and may trigger malware stages scheduled at boot. Twelve minutes and the system state are gone."),
      alt:t("Un mesaj de răscumpărare pe desktop nu este o eroare de rețea. Tratarea ca incident începe din primul minut.","A ransom note on the desktop is not a network error. Treating it as an incident starts in the first minute.")}]},
 {tp:"T+25 min",ck:"07:05",src:t("ATI, asistenta-șefă","ICU, charge nurse"),
  msg:t("„Monitoarele de pe ATI afișează erori de conectare la rețea. Pacienții sunt stabili, dar nu văd centralizat valorile.”","\"The ICU monitors are showing network connection errors. The patients are stable, but I can't see the values centrally.\""),
  q:t("Izolezi segmentul de rețea al dispozitivelor medicale?","Do you isolate the medical device network segment?"),
  o:[{t:t("Da, dar mai întâi confirmi cu personalul clinic că fiecare pacient poate fi monitorizat local, la patul lui.","Yes, but first confirm with clinical staff that every patient can be monitored locally, at the bedside."),
      d:{clin:2,data:1,legal:0,evi:1},
      c:t("Aceasta este decizia care distinge un plan de continuitate clinică de unul informatic. Izolarea protejează dispozitivele, iar verificarea prealabilă garantează că nimeni nu rămâne nesupravegheat.","This is the decision that separates a clinical continuity plan from an IT one. Isolation protects the devices; the prior check guarantees nobody is left unmonitored."),alt:null},
     {t:t("Da, imediat. Riscul de propagare către dispozitive este prea mare pentru a mai aștepta.","Yes, immediately. The risk of spreading to the devices is too high to wait."),
      d:{clin:-1,data:1,legal:0,evi:1},
      c:t("Ai protejat dispozitivele, dar ai tăiat monitorizarea centralizată fără ca secția să fie pregătită. Timp de 9 minute, doi pacienți au fost urmăriți doar prin verificare directă.","You protected the devices but cut central monitoring before the ward was ready. For nine minutes, two patients were tracked by direct observation only."),
      alt:t("Aceeași acțiune, precedată de 60 de secunde de confirmare cu asistenta-șefă, ar fi avut același efect de securitate fără riscul clinic.","The same action, preceded by 60 seconds of confirmation with the charge nurse, would have had the same security effect without the clinical risk.")},
     {t:t("Nu. Dispozitivele medicale sunt prea sensibile ca să intervii asupra lor în timpul unui incident.","No. Medical devices are too sensitive to touch during an incident."),
      d:{clin:0,data:-2,legal:0,evi:0},
      c:t("Neintervenția nu este neutră. Segmentul medical a rămas conectat la o rețea despre care nu știi ce conține, încă patru ore.","Doing nothing is not neutral. The clinical segment stayed connected to a network whose contents you do not know, for another four hours."),
      alt:t("Sensibilitatea dispozitivelor este un argument pentru segmentare pregătită dinainte, nu pentru a nu face nimic în incident.","Device sensitivity is an argument for segmentation prepared in advance, not for doing nothing during an incident.")}]},
 {tp:"T+50 min",ck:"07:30",src:t("Medic de gardă","Doctor on call"),
  msg:t("„Pot să fotografiez rezultatele de laborator cu telefonul meu și să i le trimit colegului pe WhatsApp? Altfel nu putem opera la opt.”","\"Can I photograph the lab results on my phone and send them to my colleague on WhatsApp? Otherwise we can't operate at eight.\""),
  q:t("Ce răspunzi?","What do you answer?"),
  o:[{t:t("Nu, dar activezi imediat procedura de transmitere pe hârtie: laboratorul printează, un brancardier duce fizic rezultatele în bloc.","No, but you activate the paper procedure at once: the lab prints, a porter physically carries the results to theatre."),
      d:{clin:2,data:2,legal:1,evi:0},
      c:t("Ai rezolvat nevoia clinică fără să creezi un al doilea incident de date. Aceasta este exact situația pentru care există procedura de lucru degradat — dacă există.","You met the clinical need without creating a second data incident. This is exactly the situation the degraded-mode procedure exists for — if it exists."),alt:null},
     {t:t("Da, temporar. Viața pacientului trece înaintea protecției datelor.","Yes, temporarily. The patient's life comes before data protection."),
      d:{clin:1,data:-3,legal:-2,evi:-1},
      c:t("Ai rezolvat operația și ai creat o breșă: date privind sănătatea, pe două telefoane personale, într-un serviciu pe care nu îl controlezi, fără evidență a cine le-a mai văzut.","You saved the operation and created a breach: health data on two personal phones, in a service you do not control, with no record of who else saw it."),
      alt:t("Falsa dilemă e capcana. Printarea și transportul fizic rezolvă aceeași nevoie clinică în același interval de timp.","The false dilemma is the trap. Printing and physical transport meet the same clinical need in the same time window.")},
     {t:t("Nu, și amâni operațiile până se restaurează sistemele.","No, and you postpone the operations until the systems are restored."),
      d:{clin:-3,data:2,legal:0,evi:0},
      c:t("Ai protejat datele perfect și ai amânat patru intervenții pentru o problemă care se rezolva cu o imprimantă. Doi pacienți erau pregătiți preoperator.","You protected the data perfectly and postponed four procedures over a problem a printer would have solved. Two patients were already prepped."),
      alt:t("Amânarea este o decizie clinică legitimă, dar numai după ce ai epuizat alternativele de lucru degradat.","Postponement is a legitimate clinical decision, but only after you have exhausted degraded-mode alternatives.")}]},
 {tp:"T+1h 30",ck:"08:10",src:t("Furnizorul HIS, la telefon","The HIS vendor, on the phone"),
  msg:t("„Ca să investigăm mai repede, avem nevoie de un cont de administrator de domeniu. Dați-ne acces complet și rezolvăm până la prânz.”","\"To investigate faster we need a domain administrator account. Give us full access and we'll have it sorted by midday.\""),
  q:t("Acorzi accesul?","Do you grant the access?"),
  o:[{t:t("Da, dar cu un cont creat acum, temporar, cu sesiune înregistrată și dezactivare automată după 4 ore.","Yes, but with an account created now: temporary, session recorded, auto-disabled after 4 hours."),
      d:{clin:1,data:1,legal:1,evi:2},
      c:t("Ai primit ajutorul de care ai nevoie fără să renunți la control. Sesiunea înregistrată îți va folosi și în reconstituirea de mai târziu.","You got the help you need without giving up control. The recorded session will also serve you in the later reconstruction."),alt:null},
     {t:t("Da, imediat. Nu e momentul pentru birocrație, ei cunosc sistemul.","Yes, immediately. This is no time for bureaucracy; they know the system."),
      d:{clin:1,data:-1,legal:-1,evi:-2},
      c:t("Furnizorul lucrează acum cu drepturi nelimitate, netrasabil. Dacă vectorul inițial a fost chiar conexiunea lui de mentenanță — ipoteză pe care nu ai exclus-o — tocmai ai extins compromiterea.","The vendor now works with unlimited, untraceable rights. If the initial vector was their own maintenance connection — a hypothesis you have not excluded — you have just widened the compromise."),
      alt:t("Un cont temporar cu sesiune înregistrată se creează în trei minute și nu întârzie cu nimic intervenția.","A temporary account with session recording takes three minutes to create and delays the intervention by nothing.")},
     {t:t("Nu, până nu confirmi că furnizorul nu este el însuși compromis.","No, not until you confirm the vendor is not itself compromised."),
      d:{clin:-2,data:1,legal:0,evi:0},
      c:t("Prudență justificată, dar nu ai mijloacele să confirmi asta singur, iar HIS-ul rămâne inoperabil. La ora 11:00 încă nu ai avansat.","Justified caution, but you lack the means to confirm it alone, and the HIS stays down. By 11:00 you have made no progress."),
      alt:t("Accesul controlat și limitat în timp permite avansul fără a-ți asuma riscul accesului nelimitat.","Controlled, time-limited access lets you progress without taking on the risk of unlimited access.")}]},
 {tp:"T+5h",ck:"11:40",src:t("Forum public, semnalat de un angajat","A public forum, flagged by an employee"),
  msg:t("A apărut o postare cu 40 de nume de pacienți și CNP-uri, prezentate ca „mostră”. Autorul anunță că are „întreaga bază”.","A post has appeared with 40 patient names and national ID numbers, presented as a \"sample\". The author claims to hold \"the whole database\"."),
  q:t("Declanșezi notificarea către autoritatea de protecție a datelor?","Do you trigger notification to the data protection authority?"),
  o:[{t:t("Da. Începi procedura acum, cu informațiile disponibile, și o completezi pe măsură ce afli mai mult.","Yes. You start the procedure now, with the information available, and complete it as you learn more."),
      d:{clin:0,data:1,legal:3,evi:1},
      c:t("Termenul curge de la momentul în care ai luat cunoștință, nu de la momentul în care ai aflat totul. O notificare inițială incompletă, urmată de completări, este exact ce prevede procedura.","The deadline runs from when you became aware, not from when you knew everything. An incomplete initial notification followed by updates is exactly what the procedure provides for."),alt:null},
     {t:t("Aștepți să confirmi amploarea reală înainte de a notifica ceva.","You wait to confirm the real extent before notifying anything."),
      d:{clin:0,data:0,legal:-3,evi:0},
      c:t("Ai ales să notifici când vei ști tot. Investigația va dura 11 zile. Termenul va fi depășit cu mult, iar întârzierea va fi ea însăși o problemă separată de incidentul propriu-zis.","You chose to notify once you know everything. The investigation will take 11 days. The deadline will be missed by a wide margin, and the delay becomes a problem separate from the incident itself."),
      alt:t("Notificarea etapizată există tocmai pentru că amploarea nu se cunoaște în primele zile.","Phased notification exists precisely because the extent is not known in the first days.")},
     {t:t("Notifici, dar prezinți incidentul ca indisponibilitate tehnică, fără a menționa expunerea de date.","You notify, but present the incident as a technical outage, without mentioning data exposure."),
      d:{clin:0,data:-1,legal:-4,evi:-1},
      c:t("O notificare care omite expunerea datelor nu este o notificare. Când eșantionul public va fi corelat cu raportarea ta, problema devine una de credibilitate, nu de securitate.","A notification that omits the data exposure is not a notification. When the public sample is matched against your report, the problem becomes one of credibility, not security."),
      alt:t("Un ransomware poate fi simultan indisponibilitate și breșă. Obligațiile diferă și se cumulează.","Ransomware can be both an outage and a breach at once. The obligations differ and they stack.")}]}
 ]};

S.transport={
 title:t("TMS criptat luni la ora 05:00","TMS encrypted on Monday at 05:00"),
 brief:t("38 de curse sunt în derulare, 12 trebuie încărcate până la 08:00. Nu există listă pe hârtie a curselor. Dispecerul nu poate deschide planificarea.","38 jobs are live, 12 must be loaded by 08:00. There is no paper list of the jobs. The dispatcher cannot open the plan."),
 steps:[
 {tp:"T+0",ck:"05:00",src:t("Dispecerat","Dispatch"),
  msg:t("„Nu intru în TMS. Am 38 de camioane pe drum și nu știu ce are fiecare de făcut azi.”","\"I can't get into the TMS. I have 38 trucks on the road and I don't know what each of them is supposed to do today.\""),
  q:t("Cum reconstitui planificarea zilei?","How do you reconstruct today's plan?"),
  o:[{t:t("Suni șoferii pe rând, pe ordinea plecărilor, și reconstitui pe hârtie de la ei ce transportă și unde merg.","Call the drivers one by one, in departure order, and rebuild on paper from them what they carry and where they go."),
      d:{cont:2,data:1,legal:0,evi:1},
      c:t("Lent, dar funcționează, și nu depinde de niciun sistem. În 90 de minute ai o imagine utilizabilă. Aceasta este exact informația pe care o copie offline zilnică ți-ar fi dat-o în trei minute.","Slow, but it works and depends on no system. In 90 minutes you have a usable picture. This is exactly the information a daily offline copy would have given you in three minutes."),alt:null},
     {t:t("Ceri furnizorului TMS să restaureze urgent și aștepți. Între timp, nu contactezi pe nimeni.","Ask the TMS vendor for an urgent restore and wait. Meanwhile, contact nobody."),
      d:{cont:-3,data:0,legal:0,evi:0},
      c:t("Restaurarea va dura 9 ore. Până la 08:00 au ratat încărcarea 12 curse, iar 4 clienți au aflat de la șoferi, nu de la tine.","The restore will take 9 hours. By 08:00 twelve loads have been missed, and four customers heard it from the drivers, not from you."),
      alt:t("Restaurarea și operarea degradată nu se exclud. Se fac în paralel, de oameni diferiți.","Restoration and degraded operation are not mutually exclusive. They run in parallel, by different people.")},
     {t:t("Extragi ce poți din emailurile de confirmare trimise clienților în ultimele zile.","Pull what you can from the confirmation emails sent to customers in recent days."),
      d:{cont:1,data:0,legal:0,evi:1},
      c:t("Sursă parțială, dar reală. Acoperă cursele confirmate în scris, nu și modificările telefonice din ultimele 48 de ore — exact cele mai recente.","A partial but real source. It covers jobs confirmed in writing, but not the phone changes of the last 48 hours — precisely the most recent ones."),
      alt:t("Combinată cu apelurile către șoferi, metoda devine suficientă. Singură, lasă un gol chiar în ziua critică.","Combined with calls to drivers, the method becomes sufficient. Alone, it leaves a gap on exactly the critical day.")}]},
 {tp:"T+2h",ck:"07:00",src:t("Broker, prin email","A broker, by email"),
  msg:t("„Schimbare urgentă: transportul de electronice se descarcă la alt depozit. Vă trimit adresa. Șoferul e aproape, confirmați repede.”","\"Urgent change: the electronics load is to be unloaded at a different warehouse. Address attached. The driver is close, please confirm quickly.\""),
  q:t("Execuți schimbarea?","Do you execute the change?"),
  o:[{t:t("Nu, până nu suni brokerul la numărul din contract — nu la cel din semnătura emailului — și confirmi verbal.","No, not until you call the broker on the number in the contract — not the one in the email signature — and confirm verbally."),
      d:{cont:1,data:1,legal:1,evi:2},
      c:t("Apelul durează două minute și oprește exact tiparul prin care se pierd transporturile de valoare. Brokerul confirmă că nu a trimis nimic.","The call takes two minutes and stops precisely the pattern by which high-value loads are lost. The broker confirms they sent nothing."),alt:null},
     {t:t("Da. Emailul vine din conversația reală cu brokerul, cu istoricul de mesaje dedesubt.","Yes. The email comes from the real thread with the broker, with the message history below it."),
      d:{cont:-2,data:-1,legal:-1,evi:-2},
      c:t("Istoricul de mesaje este exact ce face atacul credibil: cutia poștală a brokerului este compromisă de patru zile. Marfa ajunge la o adresă care nu există în nicio evidență.","The message history is exactly what makes the attack credible: the broker's mailbox has been compromised for four days. The goods arrive at an address that appears in no record."),
      alt:t("Presiunea de urgență combinată cu o schimbare de destinație este tiparul, nu excepția. Verificarea pe canal secundar nu are excepții.","Urgency pressure combined with a destination change is the pattern, not the exception. Second-channel verification has no exceptions.")},
     {t:t("Da, dar ceri întâi confirmare scrisă de la client, prin același email.","Yes, but first ask for written confirmation from the customer, on the same email thread."),
      d:{cont:0,data:0,legal:0,evi:-1},
      c:t("Confirmarea sosește în patru minute, convingătoare și falsă. Atacatorul controlează cutia poștală, deci controlează și confirmarea.","The confirmation arrives in four minutes, convincing and false. The attacker controls the mailbox, so they control the confirmation too."),
      alt:t("Verificarea pe același canal compromis nu verifică nimic. Canalul secundar înseamnă alt canal, nu alt mesaj.","Verification on the same compromised channel verifies nothing. A second channel means a different channel, not a different message.")}]},
 {tp:"T+6h",ck:"11:00",src:t("Client principal","Main customer"),
  msg:t("„Avem nevoie de confirmare scrisă că datele noastre comerciale nu au fost accesate. Altfel suspendăm contractul până la clarificare.”","\"We need written confirmation that our commercial data has not been accessed. Otherwise we suspend the contract pending clarification.\""),
  q:t("Ce le transmiți?","What do you send them?"),
  o:[{t:t("Ce știi cu certitudine, ce investighezi și când revii cu informații. Fără garanții pe care nu le poți susține.","What you know with certainty, what you are investigating and when you will come back. No guarantees you cannot support."),
      d:{cont:1,data:1,legal:2,evi:1},
      c:t("Clientul nu cere certitudine, cere seriozitate. Un răspuns onest cu termen ferm păstrează contractul; o garanție care se dovedește falsă îl pierde definitiv.","The customer is not asking for certainty, they are asking for seriousness. An honest answer with a firm deadline keeps the contract; a guarantee that proves false loses it for good."),alt:null},
     {t:t("Confirmi că datele lor sunt în siguranță. Nu ai nicio dovadă că ar fi fost accesate.","Confirm their data is safe. You have no evidence it was accessed."),
      d:{cont:0,data:-1,legal:-3,evi:-2},
      c:t("Absența dovezii nu este dovada absenței — mai ales cu jurnale păstrate 7 zile. Dacă apare ulterior o scurgere, declarația scrisă devine problema principală.","Absence of evidence is not evidence of absence — especially with 7-day log retention. If a leak surfaces later, that written statement becomes the main problem."),
      alt:t("„Nu avem indicii că...” și „Confirmăm că nu...” sunt afirmații diferite juridic. Prima e onestă, a doua e o garanție.","\"We have no indication that...\" and \"We confirm that not...\" are legally different statements. The first is honest, the second is a guarantee.")},
     {t:t("Nu răspunzi încă. Aștepți concluziile investigației ca să nu spui ceva greșit.","Don't answer yet. Wait for the investigation's conclusions so you don't say something wrong."),
      d:{cont:-2,data:0,legal:-1,evi:0},
      c:t("Tăcerea de 48 de ore este citită drept confirmare. Clientul suspendă contractul preventiv și anunță doi parteneri comuni.","Forty-eight hours of silence reads as confirmation. The customer suspends the contract pre-emptively and tells two mutual partners."),
      alt:t("Poți comunica procesul înainte de a avea rezultatul. Tăcerea nu este niciodată neutră într-o relație contractuală.","You can communicate the process before you have the result. Silence is never neutral in a contractual relationship.")}]},
 {tp:"T+30h",ck:t("Marți, 11:00","Tuesday, 11:00"),src:t("Telematică","Telematics"),
  msg:t("Un transport de valoare mare nu mai raportează poziția de 40 de minute. Șoferul nu răspunde la telefon.","A high-value load has not reported its position for 40 minutes. The driver is not answering the phone."),
  q:t("Cum tratezi situația?","How do you treat this?"),
  o:[{t:t("Ca posibil furt în desfășurare: anunți poliția, asigurătorul și clientul, în paralel cu verificarea tehnică.","As a possible theft in progress: alert the police, the insurer and the customer, in parallel with the technical check."),
      d:{cont:2,data:0,legal:2,evi:1},
      c:t("Pierderea semnalului pe un transport de valoare, în timpul unui incident cibernetic, nu este o coincidență până la proba contrarie. Primele 60 de minute decid dacă marfa se recuperează.","Losing signal on a high-value load during a cyber incident is not a coincidence until proven otherwise. The first 60 minutes decide whether the goods are recovered."),alt:null},
     {t:t("Ca defecțiune de telematică. Sistemul a avut probleme toată ziua.","As a telematics fault. The system has had problems all day."),
      d:{cont:-3,data:0,legal:-1,evi:-1},
      c:t("Camionul este găsit a doua zi, gol, la 60 de kilometri de rută. Cele 40 de minute au fost singura fereastră utilă.","The truck is found the next day, empty, 60 kilometres off route. Those 40 minutes were the only useful window."),
      alt:t("Aici incidentul cibernetic devine furt fizic. Scenariile care se opresc la „datele au fost criptate” ratează esențialul acestui sector.","This is where the cyber incident becomes physical theft. Scenarios that stop at \"the data was encrypted\" miss this sector's essential point.")},
     {t:t("Aștepți 30 de minute. Dacă nu revine semnalul, escaladezi.","Wait 30 minutes. If the signal doesn't return, escalate."),
      d:{cont:-1,data:0,legal:0,evi:0},
      c:t("Semnalul nu revine. Ai pierdut încă 30 de minute dintr-o fereastră care se închide, pentru a evita o alarmă falsă care nu costa nimic.","The signal does not return. You lost another 30 minutes of a closing window to avoid a false alarm that would have cost nothing."),
      alt:t("Costul unei alarme false este un telefon. Costul întârzierii este marfa.","A false alarm costs a phone call. The delay costs the load.")}]}
 ]};

S.energy={
 title:t("Pierderea vizibilității SCADA la 03:20","Loss of SCADA visibility at 03:20"),
 brief:t("Dispeceratul pierde telemetria de la toate cele 3 parcuri simultan. Producția pare să continue, dar nu poate fi confirmată și nici comandată. Furnizorul de monitorizare nu răspunde.","Dispatch loses telemetry from all 3 parks at once. Generation appears to continue, but cannot be confirmed or commanded. The monitoring provider is not answering."),
 steps:[
 {tp:"T+0",ck:"03:20",src:t("Dispecerat propriu","Own control desk"),
  msg:t("„Am pierdut telemetria de la toate trei parcurile în același minut. Nu am nicio valoare, nici măcar vechi.”","\"We lost telemetry from all three parks in the same minute. I have no values at all, not even stale ones.\""),
  q:t("Prima ipoteză de lucru?","Your first working hypothesis?"),
  o:[{t:t("Tratezi ca incident de securitate până la proba contrarie și trimiți echipaj la cel mai apropiat parc pentru citire locală.","Treat it as a security incident until proven otherwise and send a crew to the nearest park for a local reading."),
      d:{cont:2,data:1,legal:1,evi:2},
      c:t("Simultaneitatea perfectă pe trei amplasamente diferite exclude practic defecțiunea locală. Citirea la fața locului îți dă singura informație pe care o poți declara operatorului de rețea.","Perfect simultaneity across three separate sites practically rules out a local fault. The on-site reading gives you the only information you can declare to the grid operator."),alt:null},
     {t:t("Defecțiune de comunicații la furnizorul de monitorizare. Aștepți să revină.","A comms fault at the monitoring provider. Wait for it to come back."),
      d:{cont:-2,data:0,legal:-2,evi:-1},
      c:t("La 05:00 operatorul de rețea cere capacitatea disponibilă pentru ora următoare. Nu ai nici date, nici o ipoteză verificată, nici un echipaj pe teren.","At 05:00 the grid operator asks for available capacity for the coming hour. You have no data, no verified hypothesis and no crew on site."),
      alt:t("Ipoteza benignă poate fi corectă, dar nu justifică inacțiunea. Verificarea costă un drum, nu o decizie.","The benign hypothesis may be right, but it does not justify inaction. Verification costs a drive, not a decision.")},
     {t:t("Repornești legătura de comunicații de la distanță, ca să vezi dacă se restabilește.","Remotely restart the communications link to see if it re-establishes."),
      d:{cont:0,data:-1,legal:0,evi:-2},
      c:t("Nu se restabilește, iar dacă a existat activitate în segmentul de proces, tocmai ai șters urmele ei din echipamentul de comunicații.","It does not re-establish, and if there was activity in the process segment, you have just erased its traces from the comms equipment."),
      alt:t("În OT, repornirea ca primă acțiune de diagnostic distruge exact informația de care ai nevoie mai târziu.","In OT, rebooting as a first diagnostic step destroys exactly the information you will need later.")}]},
 {tp:"T+2h",ck:"05:20",src:t("Echipa IT","IT team"),
  msg:t("„Am găsit un cont de serviciu creat acum 9 zile, cu drepturi în segmentul de proces. Nu l-a cerut nimeni de la noi.”","\"We found a service account created nine days ago, with rights in the process segment. Nobody here requested it.\""),
  q:t("Îl dezactivezi imediat?","Do you disable it immediately?"),
  o:[{t:t("Îl dezactivezi, dar mai întâi salvezi jurnalele asociate și notezi toate sesiunile lui din cele 9 zile.","Disable it, but first preserve the associated logs and record all its sessions over the nine days."),
      d:{cont:1,data:2,legal:1,evi:2},
      c:t("Cinci minute de colectare îți dau harta a ceea ce a atins atacatorul. Fără ea, vei reconstrui orbește o săptămână întreagă.","Five minutes of collection give you the map of what the attacker touched. Without it, you will be rebuilding blind for a whole week."),alt:null},
     {t:t("Da, imediat. Un cont necunoscut cu drepturi în OT nu are ce căuta activ nicio secundă în plus.","Yes, immediately. An unknown account with OT rights has no business staying active a second longer."),
      d:{cont:1,data:1,legal:0,evi:-2},
      c:t("Decizie defensabilă, dar ai pierdut jurnalele de sesiune, care se rotesc la 72 de ore. Nu vei putea stabili niciodată ce a fost modificat în cele 9 zile.","A defensible decision, but you lost the session logs, which rotate at 72 hours. You will never be able to establish what was changed over those nine days."),
      alt:t("Dezactivarea și colectarea nu sunt alternative. Colectarea durează cinci minute și se face prima.","Disabling and collecting are not alternatives. Collection takes five minutes and comes first.")},
     {t:t("Nu. Îl monitorizezi, ca să vezi ce face atacatorul și de unde se conectează.","No. Monitor it to see what the attacker does and where they connect from."),
      d:{cont:-2,data:-2,legal:-1,evi:1},
      c:t("Tactică rezonabilă într-o organizație cu capacitate de monitorizare. Tu ai un informatician și niciun instrument de detecție în OT. Contul rămâne activ, nesupravegheat real, încă șase ore.","A reasonable tactic in an organisation with monitoring capability. You have one IT officer and no detection tooling in OT. The account stays active, not genuinely watched, for another six hours."),
      alt:t("Observarea unui atacator necesită capacitatea de a-l observa. În lipsa ei, este doar acces tolerat.","Watching an attacker requires the capacity to watch. Without it, it is simply tolerated access.")}]},
 {tp:"T+5h",ck:"08:20",src:t("Departamentul comercial","Trading desk"),
  msg:t("„Expunerea de dezechilibru crește cu fiecare oră în care nu putem confirma producția. Suntem deja la 40.000 de euro.”","\"Our imbalance exposure grows every hour we can't confirm generation. We're already at EUR 40,000.\""),
  q:t("Oprești producția preventiv?","Do you shut down generation pre-emptively?"),
  o:[{t:t("Nu încă. Ceri echipajelor citiri locale orare și declari operatorului de rețea valori confirmate manual, cu marjă de prudență.","Not yet. Ask the crews for hourly local readings and declare manually confirmed values to the grid operator, with a prudence margin."),
      d:{cont:2,data:1,legal:2,evi:1},
      c:t("Ai transformat o pierdere totală de vizibilitate într-o vizibilitate degradată, dar declarabilă. Expunerea se stabilizează, iar relația cu operatorul de rețea rămâne intactă.","You turned a total loss of visibility into degraded but declarable visibility. The exposure stabilises and the relationship with the grid operator stays intact."),alt:null},
     {t:t("Da. Fără vizibilitate, riscul operațional depășește orice pierdere financiară.","Yes. Without visibility, operational risk outweighs any financial loss."),
      d:{cont:-2,data:1,legal:0,evi:0},
      c:t("Decizie prudentă și costisitoare: ai pierdut cert veniturile a 14 ore pentru un risc pe care citirea locală îl reducea substanțial.","A prudent and expensive decision: you certainly lost fourteen hours of revenue against a risk that local readings would have substantially reduced."),
      alt:t("Oprirea este opțiunea corectă când nu ai nicio cale de a confirma starea instalației. Aici aveai una.","Shutting down is right when you have no way at all to confirm plant state. Here you had one.")},
     {t:t("Nu. Continui să declari valorile prognozate, ca până acum.","No. Keep declaring forecast values, as before."),
      d:{cont:0,data:0,legal:-3,evi:-1},
      c:t("Declari valori pe care nu le poți susține cu nicio măsurătoare. Dacă abaterea reală este mare, problema devine una de raportare, nu de producție.","You declare values you cannot support with any measurement. If the real deviation is large, the problem becomes one of reporting, not generation."),
      alt:t("O valoare prognozată declarată ca măsurată este o altă categorie de problemă decât o pierdere de producție.","A forecast value declared as measured is a different category of problem than a loss of generation.")}]},
 {tp:"T+24h",ck:t("A doua zi, 03:20","Next day, 03:20"),src:t("Alt producător, la telefon","Another generator, by phone"),
  msg:t("„Avem același furnizor de monitorizare și exact aceleași simptome, de acum două ore. Voi ce ați găsit?”","\"We use the same monitoring provider and we have exactly the same symptoms, from two hours ago. What did you find?\""),
  q:t("Cum schimbă asta încadrarea incidentului?","How does this change your framing of the incident?"),
  o:[{t:t("Îl reîncadrezi ca incident de lanț de aprovizionare, notifici autoritatea și propui coordonare între operatorii afectați.","Reframe it as a supply chain incident, notify the authority and propose coordination between affected operators."),
      d:{cont:2,data:1,legal:3,evi:2},
      c:t("Două organizații independente cu același furnizor și aceleași simptome nu mai este incidentul tău, este un incident sistemic. Încadrarea corectă schimbă cine trebuie să știe și cât de repede.","Two independent organisations with the same provider and the same symptoms is no longer your incident, it is a systemic one. The correct framing changes who needs to know, and how fast."),alt:null},
     {t:t("Schimbi puțin: rămâne incidentul tău, dar compari notițe informal cu celălalt producător.","Change little: it stays your incident, but compare notes informally with the other generator."),
      d:{cont:0,data:0,legal:-2,evi:1},
      c:t("Schimbul informal ajută tehnic, dar amândoi rămâneți cu o imagine parțială, iar autoritatea nu poate corela ceea ce nu i se raportează.","The informal exchange helps technically, but you both keep a partial picture, and the authority cannot correlate what is not reported to it."),
      alt:t("Recunoașterea unui incident de furnizor este ea însăși o informație pe care autoritatea o poate corela cu alte raportări.","Recognising a vendor incident is itself information the authority can correlate with other reports.")},
     {t:t("Nu comunici nimic până nu ai concluzii proprii, ca să nu răspândești informații neconfirmate.","Communicate nothing until you have your own conclusions, so as not to spread unconfirmed information."),
      d:{cont:-1,data:0,legal:-3,evi:0},
      c:t("Al treilea operator, care nu știe nimic, instalează în aceeași zi actualizarea furnizorului. Prudența ta a costat pe altcineva.","A third operator, who knows nothing, installs the provider's update that same day. Your caution cost someone else."),
      alt:t("Informația neconfirmată, marcată ca atare, este utilă. Tăcerea nu este prudență, este întârziere.","Unconfirmed information, labelled as such, is useful. Silence is not caution, it is delay.")}]}
 ]};

S.manufacturing={
 title:t("Ransomware în schimbul de noapte","Ransomware on the night shift"),
 brief:t("MES-ul devine indisponibil la 23:40. Liniile rulează pe programele deja încărcate, dar nu se mai poate înregistra trasabilitatea. Livrarea către OEM la 06:00 este contractuală, cu penalizare pe oră.","The MES goes down at 23:40. The lines run on already-loaded programs, but traceability can no longer be recorded. The 06:00 OEM delivery is contractual, with an hourly penalty."),
 steps:[
 {tp:"T+0",ck:"23:40",src:t("Șeful de tură","Shift supervisor"),
  msg:t("„MES-ul nu mai răspunde. Liniile merg, dar nu pot înregistra niciun lot. Continuăm sau oprim?”","\"The MES isn't responding. The lines are running, but I can't record a single batch. Do we carry on or stop?\""),
  q:t("Ce decizi?","What do you decide?"),
  o:[{t:t("Continui producția, dar activezi imediat înregistrarea manuală a loturilor, cu semnătura șefului de tură pe fiecare fișă.","Carry on producing, but activate manual batch recording at once, with the shift supervisor's signature on each sheet."),
      d:{cont:2,data:1,legal:2,evi:1},
      c:t("Trasabilitatea este o cerință de calitate, nu una informatică. Formularul pe hârtie o satisface, dacă există și dacă e semnat. Livrarea de la 06:00 rămâne posibilă.","Traceability is a quality requirement, not an IT one. The paper form satisfies it, if it exists and is signed. The 06:00 delivery stays possible."),alt:null},
     {t:t("Oprești liniile. Fără trasabilitate, orice piesă produsă acum este neconformă.","Stop the lines. Without traceability, any part produced now is non-conforming."),
      d:{cont:-3,data:1,legal:1,evi:0},
      c:t("Corect ca principiu de calitate, greșit ca decizie: ai oprit trei linii pentru o problemă pe care un formular o rezolva. Penalizarea curge din ora 06:00.","Right as a quality principle, wrong as a decision: you stopped three lines over a problem a form would have solved. The penalty starts running at 06:00."),
      alt:t("Oprirea este justificată doar dacă nu ai nicio metodă alternativă de înregistrare. Aici aveai una, nescrisă.","Stopping is justified only if you have no alternative recording method at all. Here you had one, just not written down.")},
     {t:t("Continui producția și înregistrezi retroactiv, când revine MES-ul.","Carry on producing and record retroactively, when the MES comes back."),
      d:{cont:1,data:0,legal:-3,evi:-2},
      c:t("Înregistrarea retroactivă, fără sursă independentă, nu este trasabilitate. La primul audit de client, loturile din noaptea aceasta devin nedemonstrabile.","Retroactive recording, with no independent source, is not traceability. At the first customer audit, tonight's batches become undemonstrable."),
      alt:t("Trasabilitatea reconstituită din memorie este exact ce declanșează o retragere de produs extinsă inutil.","Traceability reconstructed from memory is exactly what triggers an unnecessarily broad recall.")}]},
 {tp:"T+3h",ck:"02:40",src:t("Tehnician de mentenanță","Maintenance technician"),
  msg:t("„Am observat un router pe celula 3, cu SIM. L-au adus cei de la utilaje acum doi ani, pentru service la distanță. Nu e în nicio schemă.”","\"I noticed a router on cell 3, with a SIM card. The machine vendor brought it two years ago for remote service. It's on no diagram.\""),
  q:t("Ce faci cu el?","What do you do with it?"),
  o:[{t:t("Îl deconectezi fizic, îl fotografiezi cu seria vizibilă și ceri furnizorului jurnalul complet al conexiunilor.","Physically disconnect it, photograph it with the serial visible, and request the vendor's full connection log."),
      d:{cont:1,data:2,legal:2,evi:2},
      c:t("Ai închis o cale de acces despre care nimeni din firmă nu știa și ai creat prima dovadă că a existat. Întrebarea „câte altele mai sunt?” devine acum prioritatea săptămânii.","You closed an access path nobody in the company knew about and created the first evidence it existed. The question \"how many more are there?\" now becomes the week's priority."),alt:null},
     {t:t("Îl lași. Dacă îl deconectezi, pierzi suportul de la distanță pentru utilajul cel mai productiv.","Leave it. Disconnecting it loses remote support for your most productive machine."),
      d:{cont:0,data:-3,legal:-2,evi:-1},
      c:t("Ai păstrat suportul și o cale de acces necontrolată în mijlocul unui incident activ. Este exact tipul de conexiune prin care se intră în producție.","You kept the support and an uncontrolled access path in the middle of an active incident. This is precisely the kind of connection production gets entered through."),
      alt:t("Suportul de la distanță se poate reconstrui controlat în 48 de ore. Compromiterea nu se poate anula.","Remote support can be rebuilt under control in 48 hours. A compromise cannot be undone.")},
     {t:t("Îl lași conectat și ceri IT-ului să îl monitorizeze până la finalul incidentului.","Leave it connected and ask IT to monitor it until the incident ends."),
      d:{cont:0,data:-1,legal:-1,evi:0},
      c:t("IT-ul are două persoane și niciun instrument de vizibilitate în rețeaua de producție. „Monitorizat” înseamnă, practic, „lăsat conectat”.","IT has two people and no visibility tooling on the production network. \"Monitored\" means, in practice, \"left connected\"."),
      alt:t("Monitorizarea fără capacitate de monitorizare este o formulare, nu o măsură.","Monitoring without monitoring capability is a phrase, not a measure.")}]},
 {tp:"T+14h",ck:t("A doua zi, 13:40","Next day, 13:40"),src:t("Email către directorul general","Email to the managing director"),
  msg:t("Un mesaj conține contractul-cadru cu principalul client, prețurile negociate și desenele a două produse în dezvoltare. Cere plată în 72 de ore. Nimic nu este criptat.","A message contains the framework contract with your main customer, the negotiated prices and the drawings of two products in development. It demands payment within 72 hours. Nothing is encrypted."),
  q:t("Informezi clientul al cărui contract a fost expus?","Do you inform the customer whose contract was exposed?"),
  o:[{t:t("Da, în aceeași zi, direct de la conducere la conducere, cu ce s-a confirmat și ce se investighează.","Yes, the same day, leadership to leadership, with what is confirmed and what is under investigation."),
      d:{cont:1,data:2,legal:3,evi:1},
      c:t("Riști relația, dar o păstrezi. Dacă află din altă parte — și în extorcarea prin publicare află întotdeauna — pierzi contractul și credibilitatea deodată.","You risk the relationship but you keep it. If they find out elsewhere — and in leak-site extortion they always do — you lose the contract and your credibility at once."),alt:null},
     {t:t("Nu încă. Negociezi 72 de ore, ca să vezi dacă situația se poate rezolva fără ca cineva să afle.","Not yet. Play for the 72 hours and see whether this can be resolved without anyone finding out."),
      d:{cont:-1,data:-2,legal:-3,evi:0},
      c:t("Plata nu garantează nepublicarea, iar cele 72 de ore le petreci fără să pregătești nimic. Când materialul apare, clientul află de pe un site de scurgeri.","Payment does not guarantee non-publication, and you spend the 72 hours preparing nothing. When the material appears, the customer learns it from a leak site."),
      alt:t("Fereastra de 72 de ore este utilă pentru pregătirea comunicării, nu pentru amânarea ei.","The 72-hour window is useful for preparing the communication, not for postponing it.")},
     {t:t("Îl informezi, dar prezinți incidentul ca pe o „problemă tehnică” fără a menționa expunerea contractului.","Inform them, but present it as a \"technical issue\" without mentioning the contract exposure."),
      d:{cont:0,data:-1,legal:-3,evi:-1},
      c:t("Clientul află despre expunerea prețurilor peste două săptămâni, din altă sursă, și recitește mesajul tău. Problema nu mai este incidentul.","The customer learns about the price exposure two weeks later, from another source, and re-reads your message. The incident is no longer the problem."),
      alt:t("O informare care omite exact partea relevantă pentru destinatar este mai dăunătoare decât tăcerea.","A notification that omits exactly the part relevant to the recipient does more damage than silence.")}]},
 {tp:"T+36h",ck:t("A treia zi, 11:40","Day three, 11:40"),src:t("Calitate","Quality"),
  msg:t("„Nu putem demonstra trasabilitatea pentru loturile din primele 8 ore. Fișele manuale s-au început abia de la 07:00.”","\"We can't demonstrate traceability for the batches from the first 8 hours. The manual sheets only started at 07:00.\""),
  q:t("Ce faci cu loturile respective?","What do you do with those batches?"),
  o:[{t:t("Le blochezi, informezi clientul și propui reverificare pe eșantion, pe cheltuiala ta.","Block them, inform the customer and propose sample re-verification at your own cost."),
      d:{cont:1,data:1,legal:3,evi:2},
      c:t("Costisitor și corect. Un lot fără trasabilitate demonstrabilă este, formal, un lot neconform — indiferent dacă piesele sunt bune.","Expensive and correct. A batch without demonstrable traceability is formally a non-conforming batch — regardless of whether the parts are good."),alt:null},
     {t:t("Le livrezi. Piesele au trecut controlul final, deci sunt bune.","Ship them. The parts passed final inspection, so they're good."),
      d:{cont:1,data:0,legal:-4,evi:-2},
      c:t("Controlul final verifică piesa, nu lanțul. Dacă apare o problemă peste șase luni, retragerea nu se poate limita la un lot, pentru că nu știi care este lotul.","Final inspection verifies the part, not the chain. If a problem appears in six months, the recall cannot be limited to one batch, because you don't know which batch it is."),
      alt:t("Exact acesta este mecanismul prin care un incident IT devine o retragere de produs extinsă inutil.","This is exactly the mechanism by which an IT incident becomes an unnecessarily broad product recall.")},
     {t:t("Le livrezi și notezi intern rezerva, în caz că se pune problema mai târziu.","Ship them and note the reservation internally, in case it comes up later."),
      d:{cont:1,data:0,legal:-3,evi:-1},
      c:t("Nota internă demonstrează că ai știut. În cazul unei reclamații, ea devine dovada principală împotriva ta.","The internal note proves you knew. In the event of a complaint, it becomes the main evidence against you."),
      alt:t("O rezervă cunoscută și necomunicată este mai gravă decât una necunoscută.","A known but uncommunicated reservation is worse than an unknown one.")}]}
 ]};

S.finance={
 title:t("Plățile se opresc în ziua de salarii","Payments stop on payday"),
 brief:t("Vineri, în ziua cu cel mai mare volum al lunii, procesarea se oprește. Furnizorul unic spune „investigăm”, apoi confirmă un incident de securitate la el, fără detalii. Clienții sună.","On Friday, the highest-volume day of the month, processing stops. The single provider says \"we're investigating\", then confirms a security incident on their side, with no detail. Customers are calling."),
 steps:[
 {tp:"T+0",ck:"09:15",src:t("Furnizorul platformei","The platform provider"),
  msg:t("„Investigăm o problemă tehnică. Revenim cu informații.” Nimic altceva. Procesarea este oprită de 20 de minute.","\"We're investigating a technical issue. We'll come back with information.\" Nothing else. Processing has been down for 20 minutes."),
  q:t("Cum încadrezi evenimentul?","How do you frame the event?"),
  o:[{t:t("Deschizi procedura de incident major, fără a-l clasifica încă, și pornești ceasul de documentare.","Open the major incident procedure without classifying it yet, and start the documentation clock."),
      d:{cont:2,data:1,legal:3,evi:2},
      c:t("Deschiderea procedurii nu prejudecă clasificarea, dar pornește documentarea de la minutul zero. Termenele de raportare curg de la detectare, nu de la clarificare.","Opening the procedure does not prejudge classification, but it starts documentation from minute zero. Reporting deadlines run from detection, not from clarification."),alt:null},
     {t:t("Aștepți detalii de la furnizor. Nu poți clasifica un incident despre care nu știi nimic.","Wait for detail from the provider. You cannot classify an incident you know nothing about."),
      d:{cont:-1,data:0,legal:-3,evi:-2},
      c:t("Detaliile vin după șapte ore. Termenul de raportare a curs tot acest timp, iar cronologia primelor ore lipsește din dosar.","The detail arrives seven hours later. The reporting clock ran all that time, and the first hours' timeline is missing from the file."),
      alt:t("Poți documenta fără să clasifici. Nu poți însă recupera retroactiv cronologia primelor ore.","You can document without classifying. What you cannot do is recover the first hours' timeline retroactively.")},
     {t:t("Îl tratezi ca incident operațional de rutină. Furnizorul a mai avut întreruperi.","Treat it as a routine operational incident. The provider has had outages before."),
      d:{cont:0,data:-1,legal:-4,evi:-2},
      c:t("Furnizorul confirmă la ora 16:00 că a fost incident de securitate. Reîncadrarea vine cu șase ore de întârziere pe toate obligațiile.","At 16:00 the provider confirms it was a security incident. The reframing arrives six hours late on every obligation."),
      alt:t("„Problemă tehnică” în comunicarea unui furnizor nu este o clasificare, este absența uneia.","\"Technical issue\" in a provider's communication is not a classification, it is the absence of one.")}]},
 {tp:"T+1h 30",ck:"10:45",src:t("Juridic","Legal"),
  msg:t("„Ce prevede contractul cu furnizorul privind notificarea și asistența în caz de incident? Și cine este furnizorul de rezervă?”","\"What does the provider contract say about notification and assistance during an incident? And who is the fallback provider?\""),
  q:t("Cât îți ia să răspunzi?","How long does it take you to answer?"),
  o:[{t:t("Deschizi registrul furnizorilor TIC și răspunzi în cinci minute, cu clauza și termenul exact.","Open the ICT third-party register and answer in five minutes, with the clause and the exact deadline."),
      d:{cont:2,data:1,legal:3,evi:2},
      c:t("Registrul nu este birocrație: este singurul document care răspunde la această întrebare în minute, nu în zile. Furnizor de rezervă nu există, dar acum știi asta explicit.","The register is not bureaucracy: it is the only document that answers this question in minutes rather than days. There is no fallback provider, but now you know that explicitly."),alt:null},
     {t:t("Ceri cuiva să caute contractul în arhiva de documente. Durează două ore.","Ask someone to find the contract in the document archive. It takes two hours."),
      d:{cont:0,data:0,legal:-2,evi:-1},
      c:t("Contractul se găsește, dar nu conține clauză de notificare în caz de incident de securitate. Descoperi asta în mijlocul incidentului, nu înaintea lui.","The contract is found, but contains no security incident notification clause. You discover this in the middle of the incident, not before it."),
      alt:t("Registrul furnizorilor TIC este prima capabilitate cerută de DORA tocmai pentru că este utilă exact în acest moment.","The ICT third-party register is DORA's first required capability precisely because it is useful at exactly this moment.")},
     {t:t("Întrebi furnizorul ce prevede contractul.","Ask the provider what the contract says."),
      d:{cont:-1,data:0,legal:-3,evi:-1},
      c:t("Furnizorul, aflat el însuși în criză, răspunde a doua zi și invocă o limitare de răspundere pe care nu o cunoșteai.","The provider, itself in crisis, answers the next day and invokes a liability limitation you were unaware of."),
      alt:t("Partea cealaltă a contractului nu este sursa ta de informare despre propriile drepturi.","The counterparty to a contract is not your source of information about your own rights.")}]},
 {tp:"T+8h",ck:"17:15",src:t("Antifraudă","Anti-fraud"),
  msg:t("„În ultimele două ore au crescut de patru ori plățile către beneficiari adăugați azi. Clienții sună confuzi și acceptă mai ușor instrucțiuni.”","\"In the last two hours, payments to payees added today have quadrupled. Customers are calling confused and are more likely to accept instructions.\""),
  q:t("Ce faci?","What do you do?"),
  o:[{t:t("Blochezi temporar categoria „beneficiar nou” peste un prag și anunți public canalul oficial de verificare.","Temporarily block the 'new payee' category above a threshold and publicly announce the official verification channel."),
      d:{cont:1,data:2,legal:2,evi:1},
      c:t("Frauda oportunistă în timpul unei crize este regula, nu excepția. Blocajul temporar costă câteva tranzacții legitime și oprește un val.","Opportunistic fraud during a crisis is the rule, not the exception. A temporary block costs a few legitimate transactions and stops a wave."),alt:null},
     {t:t("Nu intervii. Ai deja un incident major; nu poți bloca și plățile legitime.","Don't intervene. You already have a major incident; you can't block legitimate payments too."),
      d:{cont:0,data:-2,legal:-1,evi:0},
      c:t("Până la miezul nopții, 31 de clienți au plătit către conturi controlate de atacatori. Pierderile lor devin și problema ta.","By midnight, 31 customers have paid into attacker-controlled accounts. Their losses become your problem too."),
      alt:t("Un incident nu suspendă antifrauda. Dimpotrivă, este momentul în care contează cel mai mult.","An incident does not suspend anti-fraud. On the contrary, it is when it matters most.")},
     {t:t("Ridici pragurile de alertare, ca să nu fie echipa copleșită de alarme.","Raise the alerting thresholds so the team isn't overwhelmed by alarms."),
      d:{cont:0,data:-3,legal:-2,evi:-2},
      c:t("Ai redus zgomotul suprimând exact semnalul. Modificarea pragurilor în timpul unui incident, fără control al schimbării, este o problemă în sine.","You reduced the noise by suppressing exactly the signal. Changing thresholds during an incident, without change control, is a problem in itself."),
      alt:t("Zgomotul se gestionează cu oameni în plus, nu cu praguri mai mari.","Noise is handled with more people, not higher thresholds.")}]},
 {tp:"T+16h",ck:t("Sâmbătă, 01:15","Saturday, 01:15"),src:t("Furnizorul platformei","The platform provider"),
  msg:t("„Confirmăm exfiltrarea unui set de date de client. Nu putem preciza încă volumul.”","\"We confirm exfiltration of a customer data set. We cannot yet specify the volume.\""),
  q:t("Ce declanșează asta?","What does this trigger?"),
  o:[{t:t("Ambele regimuri în paralel: raportarea incidentului major și evaluarea de breșă de date personale, cu termenele lor distincte.","Both regimes in parallel: major incident reporting and a personal data breach assessment, on their separate deadlines."),
      d:{cont:1,data:2,legal:3,evi:2},
      c:t("Incidentul legat de TIC și breșa de date sunt regimuri distincte, cu autorități și termene diferite. Se cumulează, nu se substituie.","The ICT-related incident and the personal data breach are distinct regimes, with different authorities and deadlines. They stack; they do not substitute for one another."),alt:null},
     {t:t("Aștepți ca furnizorul să precizeze volumul înainte de a porni orice notificare.","Wait for the provider to specify the volume before starting any notification."),
      d:{cont:0,data:-1,legal:-4,evi:-1},
      c:t("Volumul se precizează în 9 zile. Ambele termene sunt depășite, iar tu ai fost operatorul, nu furnizorul — obligația era a ta.","The volume is specified in nine days. Both deadlines are missed, and you were the controller, not the provider — the obligation was yours.")
      ,alt:t("Externalizarea prelucrării nu externalizează obligația de notificare.","Outsourcing the processing does not outsource the notification obligation.")},
     {t:t("Raportezi doar incidentul major. Breșa este a furnizorului, el trebuie să o notifice.","Report only the major incident. The breach is the provider's; they should notify it."),
      d:{cont:0,data:-2,legal:-3,evi:0},
      c:t("Furnizorul este persoană împuternicită. Obligația de notificare către autoritatea de protecție a datelor și către clienți îți revine ție.","The provider is a processor. The obligation to notify the data protection authority and your customers falls on you."),
      alt:t("Confuzia între operator și persoană împuternicită schimbă cine notifică. Merită clarificată înainte de incident.","Confusing controller and processor changes who notifies. It is worth clarifying before the incident.")}]}
 ]};
})();
